SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.discharge_location, d.los, c.charlson_comorbidity_cat, COUNT(CASE WHEN d.deathtime IS NOT NULL THEN 1 END)::FLOAT / NULLIF(COUNT(d.hadm_id), 0) AS mortality_rate, SUM(CASE WHEN d.los BETWEEN 1 AND 3 THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(d.hadm_id), 0) AS short_stay_rate, SUM(CASE WHEN d.los BETWEEN 4 AND 7 THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(d.hadm_id), 0) AS medium_stay_rate, SUM(CASE WHEN d.los >= 8 THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(d.hadm_id), 0) AS long_stay_rate, SUM(CASE WHEN d.discharge_location = 'home' THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(d.hadm_id), 0) AS home_discharge_rate, SUM(CASE WHEN d.discharge_location = 'rehab' THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(d.hadm_id), 0) AS rehab_discharge_rate, SUM(CASE WHEN d.discharge_location = 'SNF' THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(d.hadm_id), 0) AS SNF_discharge_rate, SUM(CASE WHEN d.discharge_location = 'hospice' THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(d.hadm_id), 0) AS hospice_discharge_rate FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays s ON a.stay_id = s.stay_id JOIN charlson c ON c.charlson_comorbidity_cat BETWEEN 3 AND 5 WHERE p.gender = 'M' AND p.anchor_age BETWEEN 58 AND 58 AND p.anchor_year BETWEEN 2013 AND 2013 AND p.anchor_year_group BETWEEN 53 AND 63 AND c.charlson_comorbidity_cat BETWEEN 1 AND 2 AND a.admission_type_id = 1 GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.discharge_location, d.los, c.charlson_comorbidity_cat;